using System.Diagnostics;

namespace McpServerManager.Director.Tests;

/// <summary>
/// Helper that invokes the Director CLI executable via <c>dotnet exec</c>
/// with the working directory set to the repository root where the
/// <c>AGENTS-README-FIRST.yaml</c> marker file lives.
/// </summary>
internal static class DirectorRunner
{
    /// <summary>Repository root ΓÇö working directory for all CLI invocations.</summary>
    internal static readonly string RepoRoot = FindRepoRoot();

    /// <summary>Current target framework for Director CLI test invocations.</summary>
    internal const string TargetFramework = "net10.0";

    /// <summary>Current build configuration for Director CLI test invocations.</summary>
    private static readonly string Configuration = GetBuildConfiguration();

    /// <summary>Path to the built <c>director.dll</c>.</summary>
    private static readonly string DirectorDll = Path.GetFullPath(
        Path.Combine(RepoRoot, "src", "McpServerManager.Director", "bin", Configuration, TargetFramework, "director.dll"));

    /// <summary>Default per-command timeout in milliseconds.</summary>
    private const int DefaultTimeoutMs = 30_000;

    /// <summary>
    /// Optional config file for the director process started by the current test.
    /// When unset, each invocation gets its own empty file so tests do not share
    /// the user profile config or each other's default URL.
    /// </summary>
    internal static readonly AsyncLocal<string?> ConfigFile = new();

    /// <summary>
    /// Runs the Director CLI with the given arguments and returns the exit code,
    /// captured stdout, and captured stderr.
    /// </summary>
    internal static Task<CliResult> RunAsync(string args, int timeoutMs = DefaultTimeoutMs)
        => RunAsync(args, workingDirectory: RepoRoot, timeoutMs: timeoutMs);

    /// <summary>
    /// Runs the Director CLI with the given arguments and a custom working directory.
    /// </summary>
    internal static async Task<CliResult> RunAsync(string args, string workingDirectory, int timeoutMs = DefaultTimeoutMs)
    {
        var psi = new ProcessStartInfo
        {
            FileName = "dotnet",
            Arguments = $"exec \"{DirectorDll}\" {args}",
            WorkingDirectory = workingDirectory,
            RedirectStandardOutput = true,
            RedirectStandardError = true,
            UseShellExecute = false,
            CreateNoWindow = true,
        };

        // Ensure ANSI markup does not leak into captured output.
        psi.Environment["NO_COLOR"] = "1";
        var configFile = ConfigFile.Value;
        if (string.IsNullOrWhiteSpace(configFile))
        {
            configFile = Path.Combine(Path.GetTempPath(), "director-cli-tests", Guid.NewGuid().ToString("N"), "director.config.json");
        }

        var configDir = Path.GetDirectoryName(configFile);
        if (!string.IsNullOrEmpty(configDir))
            Directory.CreateDirectory(configDir);
        psi.Environment["DIRECTOR_CLI_CONFIG"] = configFile;

        using var process = Process.Start(psi)!;
        var stdoutTask = process.StandardOutput.ReadToEndAsync();
        var stderrTask = process.StandardError.ReadToEndAsync();

        using var cts = new CancellationTokenSource(timeoutMs);
        try
        {
            await process.WaitForExitAsync(cts.Token).ConfigureAwait(true);
        }
        catch (OperationCanceledException)
        {
            try { process.Kill(entireProcessTree: true); } catch { /* best effort */ }
            throw new TimeoutException(
                $"Director command timed out after {timeoutMs}ms: director {args}");
        }

        var stdout = await stdoutTask.ConfigureAwait(true);
        var stderr = await stderrTask.ConfigureAwait(true);
        return new CliResult(process.ExitCode, stdout, stderr);
    }

    private static string FindRepoRoot()
    {
        // Walk up from the test assembly location to find the .sln file.
        var dir = AppContext.BaseDirectory;
        while (dir is not null)
        {
            if (File.Exists(Path.Combine(dir, "McpServer.sln")))
                return dir;
            dir = Path.GetDirectoryName(dir);
        }

        // Fallback ΓÇö assume standard repo layout relative to bin output.
        return Path.GetFullPath(
            Path.Combine(AppContext.BaseDirectory, "..", "..", "..", "..", ".."));
    }

    private static string GetBuildConfiguration()
    {
        var dir = new DirectoryInfo(AppContext.BaseDirectory);
        while (dir is not null)
        {
            if (string.Equals(dir.Name, "Debug", StringComparison.OrdinalIgnoreCase) ||
                string.Equals(dir.Name, "Release", StringComparison.OrdinalIgnoreCase))
            {
                return dir.Name;
            }

            dir = dir.Parent;
        }

        return "Debug";
    }
}

/// <summary>Result of a Director CLI invocation.</summary>
internal sealed record CliResult(int ExitCode, string StdOut, string StdErr)
{
    /// <summary>Combined stdout + stderr for assertions.</summary>
    internal string AllOutput => StdOut + StdErr;
}

